import Foundation

/// A source caption track advertised by the VISIONOS player response.
/// Its signed timedtext URL is short-lived and must remain in memory.
public struct YouTubeCaptionTrack: Sendable {
    public let languageCode: String
    public let languageName: String
    public let url: URL
    public let isAutoGenerated: Bool
    public let identifier: String

    public init(
        languageCode: String,
        languageName: String,
        url: URL,
        isAutoGenerated: Bool,
        identifier: String
    ) {
        self.languageCode = languageCode
        self.languageName = languageName
        self.url = url
        self.isAutoGenerated = isAutoGenerated
        self.identifier = identifier
    }
}
